184	// ──────────────────────────────────────────────────────────────────────────
185	//  Org chart composition — combines registry records with disk-parsed agents
186	// ──────────────────────────────────────────────────────────────────────────
187	
188	/**
189	 * Build a complete org-chart response combining:
190	 *   - Department metadata from departments.json
191	 *   - Per-agent records from registry.json
192	 *   - Live agent metadata (name, description, model, tools) from the
193	 *     caller-supplied `agentMap` keyed by filename
194	 *
195	 * `agentMap` is injected so this module stays decoupled from server.js's
196	 * agent parser. Typical caller:
197	 *
198	 *   const agentMap = Object.fromEntries(
199	 *     listAgents(path.join(CLAUDE_DIR, 'agents')).map((a) => [a.filename, a])
200	 *   );
201	 *   const chart = org.buildOrgChart(agentMap);
202	 */
203	function buildOrgChart(agentMap = {}) {
204	  const { departments, phases } = loadDepartments();
205	  const { agents: registry } = loadRegistry();
206	
207	  // Phase A — pull live load + capacity for every agent in one query so the
208	  // chart can render 🟢🟡🔴 indicators without N round-trips.
209	  // tasks lib is required lazily to avoid a circular dep at module load.
210	  let loadMap = {};
211	  try {
212	    const tasksLib = require('./lib/tasks');
213	    loadMap = tasksLib.getAllAgentLoad();
214	  } catch (err) {
215	    // Graceful degradation: no load info if tasks lib not yet available.
216	    loadMap = {};
217	  }
218	
219	  const nodes = [];
220	  const agentIds = Object.keys(registry || {});
221	
222	  for (const id of agentIds) {
223	    const record = registry[id];
224	    const disk = agentMap[id] || null;
225	
226	    // Skip if registry references an agent that has no .md file on disk
227	    // (we still keep it if status === 'probation' for new hires in flight)
228	    if (!disk && record.status !== 'probation' && record.status !== 'pending') {
229	      continue;
230	    }
231	
232	    const deptInfo = departments?.[record.department] || null;
233	
234	    // Org Structure v2: sub-department + pod resolution
235	    const subDeptInfo = (record.subDepartment && deptInfo?.subDepartments)
236	      ? deptInfo.subDepartments[record.subDepartment] || null
237	      : null;
238	
239	    const deptColor = deptInfo?.color || '#6b7280';
240	
241	    nodes.push({
242	      id,
243	      name: disk?.name || record.name || id,
244	      title: record.title || 'Agent',
245	      tier: record.tier || 'engineer',
246	      model: disk?.model || record.model || 'sonnet',
247	      tools: disk?.tools || '',
248	      description: disk?.description || record.description || '',
249	      department: record.department || null,
250	      departmentLabel: deptInfo?.label || null,
251	      departmentColor: deptColor,
252	      // Org v2 fields
253	      subDepartment: record.subDepartment || null,
254	      subDepartmentLabel: subDeptInfo?.label || null,
255	      subDepartmentDescription: subDeptInfo?.description || null,
256	      subDepartmentOrder: subDeptInfo?.order ?? 999,
257	      pod: record.pod || null,
258	      secondaryReportsTo: record.secondaryReportsTo || null,
259	      // phase removed 2026-04-28; phaseColor kept (= deptColor) for legacy tinting refs
260	      phase: null,
261	      phaseLabel: null,
262	      phaseColor: deptColor,
263	      reportsTo: record.reportsTo || null,
264	      status: record.status || 'active',
265	      level: record.level ?? null,
266	      levelTitle: record.levelTitle ?? null,
267	      yearsOfExperience: record.yearsOfExperience ?? null,
268	      experiencePoints: record.experiencePoints ?? null,
269	      tags: record.tags || { tech: [], domain: [], 'work-type': [] },
270	      squad: record.squad || null,
271	      avatar: record.avatar || null,
272	      gender: record.gender || null,
273	      // Phase A — live capacity + perf signals for the org-chart UI
274	      activeTaskCount: loadMap[id]?.activeTaskCount ?? 0,
275	      maxConcurrentTasks: loadMap[id]?.maxConcurrentTasks ?? 3,
276	      loadStatus: loadMap[id]?.loadStatus ?? 'free',
277	      busyUntilAt: loadMap[id]?.busyUntilAt ?? null,
278	      lastDispatchAt: loadMap[id]?.lastDispatchAt ?? null,
279	      successRate: typeof record.stats?.successRate === 'number' ? record.stats.successRate : null,
280	      avgDurationMs: record.stats?.avgDurationMs ?? null,
281	    });
282	  }
283	
284	  // Edges: reporting lines
285	  const nodeById = Object.fromEntries(nodes.map((n) => [n.id, n]));
286	  const edges = [];
287	  for (const node of nodes) {
288	    if (node.reportsTo && nodeById[node.reportsTo]) {
289	      edges.push({ from: node.reportsTo, to: node.id });
290	    }
291	  }
292	
293	  // Departments in org view (Org Structure v2 — includes subDepartments map)
294	  const departmentList = Object.values(departments || {})
295	    .filter((d) => d.active !== false)
296	    .sort((a, b) => (a.order || 0) - (b.order || 0))
297	    .map((d) => {
298	      const members = nodes.filter((n) => n.department === d.id);
299	      // Sub-department buckets (sorted by subDepartmentOrder, then alphabetical)
300	      const subDepartments = Object.values(d.subDepartments || {})
301	        .sort((a, b) => (a.order ?? 999) - (b.order ?? 999))
302	        .map((sd) => ({
303	          id: sd.id,
304	          label: sd.label,
305	          description: sd.description,
306	          order: sd.order ?? 999,
307	          pod: sd.pod || null,
308	          members: members
309	            .filter((n) => n.subDepartment === sd.id)
310	            .sort((a, b) => {
311	              // Leadership tier first inside a sub-dept, then by id
312	              if (a.tier === 'leadership' && b.tier !== 'leadership') return -1;
313	              if (a.tier !== 'leadership' && b.tier === 'leadership') return 1;
314	              return a.id.localeCompare(b.id);
315	            }),
316	        }));
317	      // Orphans: members in this department but with no/unknown subDepartment
318	      const knownSubIds = new Set(subDepartments.map((s) => s.id));
319	      const orphanMembers = members.filter((n) => !n.subDepartment || !knownSubIds.has(n.subDepartment));
320	
321	      return {
322	        id: d.id,
323	        label: d.label,
324	        description: d.description,
325	        color: d.color,
326	        icon: d.icon,
327	        head: d.head,
328	        members,
329	        subDepartments,
330	        orphanMembers,
331	      };
332	    });
333	
334	  // Stats
335	  const stats = {
336	    totalAgents: nodes.length,
337	    byModel: {},
338	    byTier: {},
339	    byDepartment: {},
340	    byStatus: {},
341	    byLevel: {},
342	  };
343	  for (const n of nodes) {
344	    stats.byModel[n.model] = (stats.byModel[n.model] || 0) + 1;
345	    stats.byTier[n.tier] = (stats.byTier[n.tier] || 0) + 1;
346	    if (n.department) stats.byDepartment[n.department] = (stats.byDepartment[n.department] || 0) + 1;
347	    stats.byStatus[n.status] = (stats.byStatus[n.status] || 0) + 1;
348	    if (n.level != null) stats.byLevel[n.level] = (stats.byLevel[n.level] || 0) + 1;
349	  }
350	
351	  return {
352	    nodes,
353	    edges,
354	    phases: [],
355	    departments: departmentList,
356	    stats,
357	  };
358	}
