360	// ──────────────────────────────────────────────────────────────────────────
361	//  Self-heal: detect drift between registry and disk
362	// ──────────────────────────────────────────────────────────────────────────
363	
364	/**
365	 * Compare registry.json against the actual agent .md files on disk.
366	 * Returns { onlyOnDisk: [], onlyInRegistry: [] } — agents present in one
367	 * but not the other. HR uses this to auto-heal the registry.
368	 */
369	function detectDrift(agentMap) {
370	  const { agents: registry } = loadRegistry();
371	  const registryIds = new Set(Object.keys(registry || {}));
372	  const diskIds = new Set(Object.keys(agentMap));
373	
374	  const onlyOnDisk = [...diskIds].filter((id) => !registryIds.has(id));
375	  const onlyInRegistry = [...registryIds].filter(
376	    (id) => !diskIds.has(id) && registry[id].status !== 'probation'
377	  );
378	
379	  return { onlyOnDisk, onlyInRegistry };
380	}
